  for(int n=0;n<2;n++){final int side=n;paneReload[n]=add(row,"",()->reloadPane(side));}add(row,"Reload both apps",this::retryLayout);add(row,"Choose apps",()->end(true));add(row,"End layout",()->end(false));add(row,"Shortcut setup",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));
