 private void enqueue(Runnable task){if(queue.isShutdown())return;try{queue.execute(task);}catch(RejectedExecutionException ignored){logEvent("worker_closed");}}
 private void logEvent(String event){android.util.Log.i("KinegraLayout","event="+event+" generation="+generation+" host="+getTaskId()+" started="+started+" linked0="+linked[0]+" linked1="+linked[1]);}
 private void showWarning(String message,boolean actions){if(warning==null||!visible||ending)return;warningText.setText(message);warning.getChildAt(1).setVisibility(actions?View.VISIBLE:View.GONE);warning.setVisibility(View.VISIBLE);warning.bringToFront();warningActive=actions;updateReloadButtons();}
 private void showFailure(WindowBrokerClient.Result result){failedPanes=result.failedPanes;updateReloadButtons();if(recoveryNotice.observe(failedPanes,result.message))showWarning(result.message,true);}
 private void hideWarning(){if(warning!=null)warning.setVisibility(View.GONE);warningActive=false;}
 private void retryLayout(){if(starting||ending)return;if(controls!=null)controls.dismiss();generation++;recoveryNotice.resolved();started=false;starting=false;startupFailure=null;main.removeCallbacks(startupTimeout);main.postDelayed(startupTimeout,12000);logEvent("retry");if(recoveryReady)startPair();else{final int g=generation;LocalAdbBootstrap.checkRecovery(new LocalAdbBootstrap.Listener(){public void status(String text){}public void done(boolean ok,String text){if(g!=generation||!visible||ending)return;recoveryReady=ok;if(ok)startPair();else showWarning(text,true);}});}}
 private String paneRole(int side){return PaneRecoveryPolicy.role(side,ProjectionGeometry.isPip(state.mode),state.swapped);}
 private void updateReloadButtons(){for(int n=0;n<2;n++){String label="Reload "+paneRole(n)+" app";if(paneReload[n]!=null){paneReload[n].setText(label);paneReload[n].setEnabled(started&&(reloadingPanes&(1<<n))==0);}if(warningReload[n]!=null){warningReload[n].setText(label);warningReload[n].setVisibility(started&&PaneRecoveryPolicy.failed(failedPanes,n)?View.VISIBLE:View.GONE);warningReload[n].setEnabled((reloadingPanes&(1<<n))==0);}}}
 private void reloadPane(int side){if(!visible||ending||!started||(reloadingPanes&(1<<side))!=0)return;final int g=generation;reloadingPanes|=1<<side;recoveryNotice.resolved();if(controls!=null)controls.dismiss();showWarning("Reloading "+paneRole(side)+" app…",false);logEvent("reload_pane_"+side);enqueue(()->{WindowBrokerClient.Result result=CanvasClient.call(CanvasClient.RELOAD,null,null,side,0,0);main.post(()->{if(g!=generation||!visible||ending)return;reloadingPanes&=~(1<<side);failedPanes=result.failedPanes;lastAction="reload pane "+side+(result.ok?" ready":" failed");if(result.ok){if(failedPanes==0){recoveryNotice.resolved();hideWarning();}else{recoveryNotice.observe(failedPanes,"Another app still needs attention.");showWarning("Another app still needs attention.",true);}updateReloadButtons();focus(side);}else{failedPanes|=1<<side;recoveryNotice.observe(failedPanes,result.message);showWarning(result.message,true);}logEvent(result.ok?"reload_ready":"reload_warning");});});}
 private Button add(LinearLayout row,String label,Runnable action){Button b=button(label,action);b.setTextSize(14);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(dp(3),0,dp(3),0);row.addView(b,p);return b;}
 private Button add(GridLayout grid,String label,Runnable action){Button b=button(label,action);b.setTextSize(14);GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.setMargins(dp(3),dp(3),dp(3),dp(3));grid.addView(b,p);return b;}
 private void arrange(){if(root==null||root.getWidth()<320||releasing)return;int w=root.getWidth(),h=root.getHeight();ProjectionGeometry.Box[] boxes=ProjectionGeometry.compute(w,h,state.mode,state.size,state.swapped,state.split);
  int[][] sizes=new int[2][];int total=0;for(int i=0;i<2;i++){sizes[i]=ProjectionGeometry.viewport(boxes[i],w,h,ProjectionGeometry.isPip(state.mode));total+=sizes[i][0];}float scale=Math.min(1f,Math.min(w/(float)total,h/720f));
  for(int i=0;i<2;i++){views[i].setZOrderMediaOverlay(ProjectionGeometry.isPip(state.mode) && i==(state.swapped?0:1));ProjectionGeometry.Box box=boxes[i];int[] size={Math.round(sizes[i][0]*scale),Math.round(sizes[i][1]*scale)};render[i]=size;FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(box.w,box.h);p.leftMargin=box.x;p.topMargin=box.y;views[i].setLayoutParams(p);views[i].getHolder().setFixedSize(size[0],size[1]);final int side=i;views[i].post(()->prepare(side));}
  if(ProjectionGeometry.isPip(state.mode)){views[state.swapped?0:1].bringToFront();}if(warning!=null)warning.bringToFront();describe();
 }
 private void describe(){if(shortcutSetup!=null)shortcutSetup.setVisibility(sessionShortcutsEnabled()?View.GONE:View.VISIBLE);boolean pip=ProjectionGeometry.isPip(state.mode);updateReloadButtons();if(firstApp!=null){firstApp.setText(pip?"Use main app":"Use left app");secondApp.setText(pip?"Use PiP app":"Use right app");swapButton.setText(pip?"Swap big / small":"Swap left / right");}if(status!=null&&startupFailure!=null){status.setText("Could not start the layout\n"+startupFailure);return;}if(status!=null)status.setText(ProjectionGeometry.NAMES[state.mode]+(ProjectionGeometry.isPip(state.mode)?" • "+state.size+"% inset • full-size app perspective":state.mode==ProjectionGeometry.ADJUSTABLE?" • "+state.split+":"+(100-state.split):"")+"  |  "+(started?"App viewports connected":"Preparing viewports")+(sessionShortcutsEnabled()?"":"  |  Back-hold off: enable session shortcuts"));}
 private void browserHelp(){AlertDialog d=new AlertDialog.Builder(this).setTitle("TV Bro page zoom").setMessage("Choose Use left app / Use right app in Split View, or Use main app / Use PiP app in PiP, to focus TV Bro. Close the keyboard if open. In cursor mode, hold the centre OK button on the page until the cursor menu appears. If links are being selected directly, press Back to leave direct navigation first. Left is zoom out (−); Right is zoom in (+). Repeat to adjust.\n\nThis is TV Bro's page zoom; other browsers have their own controls. Music Assistant's web page stays in this pane. Playing to a Cast receiver can open a different full-screen app.").setPositiveButton("Got it",null).create();d.show();mapDialogKeys(d);}
 private void mapDialogKeys(AlertDialog d){d.setOnKeyListener((dialog,key,e)->{if(key==KeyEvent.KEYCODE_BUTTON_B){if(e.getAction()==KeyEvent.ACTION_UP)d.dismiss();return true;}if(key==KeyEvent.KEYCODE_BUTTON_A||((key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER)&&d.getCurrentFocus() instanceof SeekBar)){if(e.getAction()==KeyEvent.ACTION_UP){if(d.getCurrentFocus() instanceof SeekBar)d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();else if(d.getCurrentFocus()!=null)d.getCurrentFocus().performClick();}return true;}return false;});}
 private void adjustSplit(){
  LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(22),dp(12),dp(22),dp(12));TextView caption=text("",18,FG);body.addView(caption);SeekBar slider=new SeekBar(this);slider.setFocusable(true);slider.setFocusableInTouchMode(true);slider.setMax(60);slider.setKeyProgressIncrement(1);int initial=state.split;if(root.getWidth()>0&&!ProjectionGeometry.isPip(state.mode)){ProjectionGeometry.Box[] boxes=ProjectionGeometry.compute(root.getWidth(),root.getHeight(),state.mode,state.size,false,state.split);initial=Math.round(boxes[0].w*100f/root.getWidth());}initial=Math.max(20,Math.min(80,initial));slider.setProgress(initial-20);caption.setText("Left "+initial+"% / Right "+(100-initial)+"% — Left / Right adjusts");body.addView(slider,new LinearLayout.LayoutParams(-1,dp(54)));body.addView(text("Changes apply when you choose Apply. Some apps reload when resized. Both panes stay visible. Fit 16:9 video is exact on a sufficiently wide screen; bars inside a video may remain.",14,MUTED));slider.setContentDescription("Left pane percentage. Left or right changes one percent.");slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int v,boolean user){caption.setText("Left "+(v+20)+"% / Right "+(80-v)+"% — Left / Right adjusts");}});
  AlertDialog d=new AlertDialog.Builder(this).setTitle("Adjust split").setView(body).setPositiveButton("Apply",(dialog,which)->{state.split=slider.getProgress()+20;state.mode=ProjectionGeometry.ADJUSTABLE;state.save();arrange();}).setNegativeButton("Cancel",null).create();d.show();mapDialogKeys(d);slider.post(()->slider.requestFocus());
 }
 private Bundle spec(){Bundle b=new Bundle();b.putInt("host",getTaskId());b.putBinder("lifetime",lifetime);for(int i=0;i<2;i++){b.putParcelable("parent"+i,views[i].getSurfaceControl());b.putInt("width"+i,render[i][0]);b.putInt("height"+i,render[i][1]);}return b;}
 private void prepare(int side){if(releasing||!visible||render[side][0]==0||!views[side].getSurfaceControl().isValid())return;linked[side]=true;if(started){final int g=generation;Bundle b=spec();enqueue(()->{WindowBrokerClient.Result r=CanvasClient.call(CanvasClient.UPDATE,null,null,0,b);if(!r.ok)main.post(()->{if(g==generation&&visible&&!ending)showFailure(r);});});}else startPair();}
 private void startPair(){if(started||starting||!visible||!recoveryReady||!linked[0]||!linked[1]||releasing)return;starting=true;startupFailure=null;showWarning("Starting app viewports…",false);describe();int g=generation;Bundle b=spec();logEvent("start_begin");
  enqueue(()->{WindowBrokerClient.Result r=CanvasClient.call(CanvasClient.START,state.left,state.right,0,b);main.post(()->{if(g!=generation||!visible||ending)return;starting=false;logEvent(r.ok?"start_ready":"start_warning");started=r.ok;if(r.ok){RecentApps.record(this,state.right);RecentApps.record(this,state.left);startupFailure=null;state.active=true;state.save();main.removeCallbacks(startupTimeout);hideWarning();describe();showControls();}else{startupFailure=r.message;lastAction="start failed: "+r.message;state.active=false;state.save();showWarning(startupFailure,true);describe();}});});
 }
 static Bundle diagnostics(){Bundle b=new Bundle();PairCanvasActivity a=current;if(a==null){b.putBoolean("canvas",false);return b;}b.putBoolean("canvas",true);b.putBoolean("visible",a.visible);b.putBoolean("started",a.started);b.putBoolean("controls",a.controlsVisible());b.putBoolean("warningVisible",a.warning!=null&&a.warning.getVisibility()==View.VISIBLE);b.putBoolean("warningSuppressed",a.recoveryNotice.suppressed());b.putInt("failedPanes",a.failedPanes);b.putInt("reloadingPanes",a.reloadingPanes);b.putBoolean("swapped",a.state.swapped);b.putInt("mode",a.state.mode);b.putInt("size",a.state.size);b.putInt("split",a.state.split);b.putString("lastAction",a.lastAction);for(int n=0;n<2;n++){b.putInt("display"+n,0);b.putInt("renderWidth"+n,a.render[n][0]);b.putInt("renderHeight"+n,a.render[n][1]);}return b;}
 boolean sessionVisible(){return visible&&started&&!ending;}
 boolean controlsVisible(){return controls!=null&&controls.isShowing();}
 void swapViews(){runOnUiThread(()->{state.swapped=!state.swapped;state.save();arrange();if(!controlsVisible())focus(state.swapped?1:0);});}
 void showControls(){runOnUiThread(()->{if(controls==null||ending||!visible||isDestroyed())return;describe();controls.show();controls.getWindow().setBackgroundDrawableResource(android.R.color.transparent);controls.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);controls.getWindow().setGravity(started?Gravity.BOTTOM:Gravity.CENTER);controls.getWindow().setLayout(-1,-2);if(started)enqueue(()->CanvasClient.call(CanvasClient.FOCUS,null,null,2,0,0));LinearLayout row=(LinearLayout)((HorizontalScrollView)hud.getChildAt(1)).getChildAt(0);row.getChildAt(0).requestFocus();});}
 private void focus(int side){if(!started){status.setText("Wait for both apps to open");return;}controls.dismiss();main.postDelayed(()->{if(!visible||ending)return;enqueue(()->{WindowBrokerClient.Result r=CanvasClient.call(CanvasClient.FOCUS,null,null,side,0,0);lastAction=(r.ok?"focus ok: ":"focus failed: ")+r.message;if(!r.ok)main.post(()->{if(visible&&!ending)showFailure(r);});});},300);}
 void forwardBack(int key){if(sessionVisible())enqueue(()->CanvasClient.call(CanvasClient.BACK,null,null,key,0,0));}
 private void end(boolean choose){if(ending)return;ending=true;state.active=false;state.save();enqueue(()->{CanvasClient.call(CanvasClient.SUSPEND,null,null,0,0,0);main.post(()->{if(controls!=null)controls.dismiss();releaseDisplays();startActivity(new Intent(this,choose?PairActivity.class:DashboardActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));finishAndRemoveTask();});});}
 private void releaseDisplays(){releasing=true;generation++;recoveryNotice.resolved();reloadingPanes=failedPanes=0;for(int n=0;n<2;n++){linked[n]=false;}started=starting=false;releasing=false;}
 @Override public void onStart(){super.onStart();if(root==null)return;visible=true;logEvent("resume");current=this;main.removeCallbacks(health);main.postDelayed(health,5000);main.postDelayed(startupTimeout,12000);root.post(()->{if(!started)showWarning("Preparing app viewports…",false);final int g=generation;LocalAdbBootstrap.checkRecovery(new LocalAdbBootstrap.Listener(){public void status(String text){}public void done(boolean ok,String text){if(!visible||ending||g!=generation)return;if(ok){recoveryReady=true;for(int n=0;n<2;n++)prepare(n);}else{startupFailure=text;main.removeCallbacks(startupTimeout);showWarning(startupFailure,true);describe();}}});});}
 @Override public void onStop(){logEvent("stop");hideWarning();visible=false;recoveryReady=false;main.removeCallbacks(startupTimeout);if(root==null){super.onStop();return;}main.removeCallbacks(health);if(controls!=null)controls.dismiss();releaseDisplays();if(!ending)enqueue(()->CanvasClient.call(CanvasClient.SUSPEND,null,null,0,0,0));super.onStop();}
 @Override public void onDestroy(){if(current==this)current=null;if(controls!=null)controls.dismiss();releaseDisplays();queue.shutdown();super.onDestroy();}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);if(i.getBooleanExtra("new_layout",false)){setIntent(i);recreate();return;}if(root==null)return;if(i.getBooleanExtra("controls",false))showControls();root.post(()->{for(int n=0;n<2;n++)prepare(n);});}
 private void backAction(){if(!started||!WindowBrokerClient.connected())end(true);else focus(state.swapped?1:0);}
 @Override public void onBackPressed(){if(!started||!WindowBrokerClient.connected()||controlsVisible())backAction();else showControls();}
